@startuml

class GasStation {
  + Address : string
}

class Pump {
  + CurrentLevel : double
  + ReorderingLevel : double
  + CriticalLevel : double
  + Status : string
}

class Gasoline {
  + Type : string
}

class Customer {
  + Status : string
  + Slack : int
}

class RefuelCard {
  + CardNumber : string
  + IsBlocked : boolean
}

class RefuelTurn {
  + Amount : double
  + Timestamp : datetime
}

class Invoice {
  + Month : string
  + TotalAmount : double
  + Discount : double
}

class Payment {
  + PaymentDate : date
  + Amount : double
}

class Reservoir {
  + QuantityToOrder : double
}

class DailyReport {
  + ReportDate : date
}

GasStation "1" *-- "*" Pump
Pump "1" -- "1" Gasoline
Pump "1" -- "1" Reservoir
Pump "1" -- "0..1" Customer : uses
Pump "1" -- "0..*" RefuelTurn : performs
Customer "1" -- "0..1" RefuelCard
Customer "1" -- "*" RefuelTurn : makes
Customer "1" -- "*" Invoice : receives
Invoice "1" -- "*" RefuelTurn : includes
Invoice "1" -- "*" Payment : settled by

@enduml

